/**
 * Nginx structured access-log evidence trail - deterministic config checks.
 *
 * WHAT THIS LOCKS
 * ---------------
 * Public 5xx/timeout incidents must be diagnosable from bounded host/container
 * log evidence without leaking request content. This is NOT a metrics backend.
 *
 *   1. static    - the log format carries exactly the allowed fields, never a
 *                  query string, cookie, Authorization, client IP or raw path;
 *                  the route classifier is a bounded map with a safe fallback;
 *                  X-Request-ID is generated by Nginx, forwarded upstream and
 *                  returned with `always`; health log suppression, redirects,
 *                  TLS, body limit, WebSocket upgrade and timeouts are intact;
 *                  the compose file mounts the fragment read-only;
 *                  the public-route deployment gate is still present.
 *   2. docker    - (skipped with a reason when Docker, the local nginx:alpine
 *                  image or openssl is unavailable) `docker compose config`
 *                  accepts the prod file and the official nginx image accepts the
 *                  assembled config through `nginx -t`.
 */
import { describe, expect, it } from "vitest";
import { spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync, copyFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ENV_FILE_SERVICES } from "../ci/phase997-candidate-gate.mjs";

const REPO = process.cwd();
const read = (...p: string[]) => readFileSync(join(REPO, ...p), "utf8").replace(/\r\n/g, "\n");

const obs = read("deploy", "nginx", "00-observability.conf");
const def = read("deploy", "nginx", "default.conf");
const compose = read("docker-compose.prod.yml");
const deploy = read(".github", "workflows", "deploy.yml");

/** Config text without comment lines. */
const code = (s: string) =>
  s
    .split("\n")
    .filter((l) => !l.trim().startsWith("#"))
    .join("\n");

const obsCode = code(obs);
const defCode = code(def);

function logFormat(): string {
  const m = /log_format\s+hermes_json\s+escape=json([\s\S]*?);/.exec(obsCode);
  expect(m, "log_format hermes_json escape=json").not.toBeNull();
  return m![1];
}

function routeMapEntries(): Array<{ pattern: string; value: string }> {
  const m = /map\s+\$uri\s+\$hermes_route_class\s*\{([\s\S]*?)\n\}/.exec(obsCode);
  expect(m, "route class map").not.toBeNull();
  return m![1]
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => {
      const mm = /^(\S+)\s+(\S+);$/.exec(l);
      expect(mm, `map entry: ${l}`).not.toBeNull();
      return { pattern: mm![1], value: mm![2] };
    });
}

/** Mirror of the Nginx classifier: first matching regex wins, else default. */
function classify(uri: string): string {
  const entries = routeMapEntries();
  const fallback = entries.find((e) => e.pattern === "default")!.value;
  for (const e of entries) {
    if (!e.pattern.startsWith("~")) continue;
    if (new RegExp(e.pattern.slice(1)).test(uri)) return e.value;
  }
  return fallback;
}

describe("00-observability.conf (http-context fragment)", () => {
  it("contains only http-level directives (no server/location)", () => {
    expect(obsCode).not.toMatch(/\bserver\s*\{/);
    expect(obsCode).not.toMatch(/\blocation\s/);
    expect(obsCode).toMatch(/log_format\s+hermes_json/);
  });

  it("logs exactly the allowed fields as one escaped JSON object", () => {
    const fmt = logFormat();
    const keys = [...fmt.matchAll(/"([a-z_]+)":/g)].map((m) => m[1]);
    expect(keys).toEqual([
      "timestamp",
      "request_id",
      "method",
      "route_class",
      "status",
      "upstream_status",
      "request_time",
      "upstream_response_time",
      "host",
      "protocol",
    ]);
    expect(fmt).toContain("$request_id");
    expect(fmt).toContain("$hermes_route_class");
    expect(fmt).toContain("$status");
    expect(fmt).toContain("$upstream_status");
    expect(fmt).toContain("$request_time");
    expect(fmt).toContain("$upstream_response_time");
  });

  it("never references request content, identity or network-origin variables", () => {
    const fmt = logFormat();
    const forbidden = [
      "$request_uri", "$uri", "$args", "$query_string", "$is_args", "$request\\b", "$request_body",
      "$http_", "$cookie_", "$remote_addr", "$remote_user", "$proxy_add_x_forwarded_for",
      "$realip", "$binary_remote_addr", "$http_user_agent", "$http_referer", "$http_authorization",
      "$host\\b", "$request_method\\b",
    ];
    for (const f of forbidden) expect(fmt, f).not.toMatch(new RegExp(f.replace(/\$/g, "\\$")));
    // host/method are emitted only through their fixed-vocabulary maps.
    expect(fmt).toContain("$hermes_log_host");
    expect(fmt).toContain("$hermes_log_method");
  });

  it("has a bounded route classifier with a safe fallback", () => {
    const entries = routeMapEntries();
    expect(entries.find((e) => e.pattern === "default")?.value).toBe("other_public");
    const values = new Set(entries.map((e) => e.value));
    expect(values.size).toBeLessThanOrEqual(30);
    for (const v of values) expect(v).toMatch(/^[a-z_]+$/);
    // labels are literals: no variable interpolation, no regex capture reuse
    for (const e of entries) expect(e.value).not.toContain("$");
  });

  it.each([
    ["/fa", "locale_root_fa"], ["/en/", "locale_root_en"], ["/de", "locale_root_de"], ["/ar", "locale_root_ar"],
    ["/en/platform", "platform"], ["/fa/platform/overview", "platform"],
    ["/en/services/plc", "services"], ["/fa/services/scada-hmi", "services"],
    ["/en/industrial-brain", "industrial_brain"], ["/fa/brain", "industrial_brain"],
    ["/en/articles", "articles"], ["/fa/articles/some-slug", "articles"],
    ["/fa/library", "library"], ["/en/careers", "careers"],
    ["/robots.txt", "robots"], ["/sitemap.xml", "sitemap"], ["/sitemap-0.xml", "sitemap"],
    ["/api/health", "health"], ["/api/health/ready", "health"],
    ["/api/admin/observability", "api"],
    ["/.well-known/acme-challenge/abc", "acme_challenge"],
    ["/_next/static/chunks/a.js", "next_static"],
  ])("classifies %s as %s", (uri, expected) => {
    expect(classify(uri)).toBe(expected);
  });

  it("never turns dynamic or hostile paths into raw labels", () => {
    const allowed = new Set(routeMapEntries().map((e) => e.value));
    const hostile = [
      "/fa/articles/user@example.com", "/en/careers/apply?token=abc", "/%0a%22x", "/../../etc/passwd",
      "/random/" + "a".repeat(4000), "/en/unknown-section/123", "/xfa/platform", "/fa/platformx",
      "/x/api/health", "/en/services-evil",
    ];
    for (const uri of hostile) {
      const label = classify(uri);
      expect(allowed.has(label), uri).toBe(true);
      expect(label.length).toBeLessThan(32);
    }
    expect(classify("/en/unknown-section/123")).toBe("other_public");
    expect(classify("/fa/platformx")).toBe("other_public");
    expect(classify("/xfa/platform")).toBe("other_public");
  });

  it("maps host and method onto fixed vocabularies with a safe default", () => {
    expect(obsCode).toMatch(/map\s+\$host\s+\$hermes_log_host\s*\{[^}]*default\s+other;/);
    expect(obsCode).toMatch(/map\s+\$request_method\s+\$hermes_log_method\s*\{[^}]*default\s+OTHER;/);
  });
});

describe("default.conf correlation id and access log", () => {
  it("logs both vhosts to stdout with the structured format", () => {
    const hits = defCode.match(/access_log\s+\/dev\/stdout\s+hermes_json;/g) ?? [];
    expect(hits).toHaveLength(2);
    expect(defCode).not.toMatch(/access_log\s+\/var\/log/);
  });

  it("returns Nginx's own $request_id on every response, including errors", () => {
    const hits = defCode.match(/add_header\s+X-Request-ID\s+\$request_id\s+always;/g) ?? [];
    expect(hits).toHaveLength(2);
    // client-supplied ids are never echoed or trusted
    expect(defCode).not.toMatch(/\$http_x_request_id/i);
  });

  it("forwards the id upstream and hides any upstream copy (no duplicate headers)", () => {
    expect((defCode.match(/proxy_set_header\s+X-Request-ID\s+\$request_id;/g) ?? []).length).toBe(2);
    expect((defCode.match(/proxy_hide_header\s+X-Request-ID;/g) ?? []).length).toBe(2);
  });

  it("keeps health log suppression, redirects, TLS, body limit, WebSocket and timeouts", () => {
    expect(defCode).toMatch(/location = \/api\/health\s*\{[\s\S]*?access_log off;/);
    expect(defCode).toContain("return 308 https://hermesnovin.com$request_uri;");
    expect(defCode).toContain("ssl_protocols TLSv1.2 TLSv1.3;");
    expect(defCode).toContain("client_max_body_size 50M;");
    expect(defCode).toContain("proxy_set_header Upgrade $http_upgrade;");
    expect(defCode).toContain('proxy_set_header Connection "upgrade";');
    expect(defCode).toContain("proxy_read_timeout 300s;");
    expect(defCode).toContain("proxy_connect_timeout 75s;");
    expect(defCode).toContain("proxy_send_timeout 300s;");
    expect(defCode).toContain("location /.well-known/acme-challenge/");
  });

  it("does not touch CSP (set by the application, not by Nginx)", () => {
    expect(defCode).not.toMatch(/Content-Security-Policy/i);
  });
});

describe("docker-compose.prod.yml wiring", () => {
  it("mounts the fragment read-only before default.conf, without dropping any mount", () => {
    const frag = "./deploy/nginx/00-observability.conf:/etc/nginx/conf.d/00-observability.conf:ro";
    const defMount = "./deploy/nginx/default.conf:/etc/nginx/conf.d/default.conf:ro";
    expect(compose).toContain(frag);
    expect(compose.indexOf(frag)).toBeLessThan(compose.indexOf(defMount));
    for (const keep of [
      "./deploy/nginx/mail.conf:/etc/nginx/conf.d/mail.conf:ro",
      "/etc/letsencrypt:/etc/letsencrypt:ro",
      "./deploy/certbot/www:/var/www/certbot:ro",
    ]) expect(compose).toContain(keep);
  });

  it("keeps the bounded Docker json-file retention and nginx health check", () => {
    const nginx = compose.slice(compose.indexOf("\n  nginx:\n"));
    expect(nginx).toContain('max-size: "20m"');
    expect(nginx).toContain('max-file: "5"');
    expect(nginx).toContain("nginx -t 2>/dev/null && wget -qO- http://localhost/api/health");
  });
});

describe("public-route deployment gate stays intact", () => {
  it("still probes the core public routes after readiness", () => {
    expect(deploy).toContain("public route probe failed for ${HG_ROUTE}.");
    expect(deploy).toContain("/robots.txt /sitemap.xml");
    expect(deploy).toContain("/fa/platform /en/services/plc /fa/services/scada-hmi");
  });
});

// ── Docker-backed validation (skipped with a reason when unavailable) ─────────

function run(cmd: string, args: string[], timeout = 60_000) {
  return spawnSync(cmd, args, { encoding: "utf8", timeout });
}
const dockerOk = run("docker", ["info", "--format", "{{.ServerVersion}}"], 20_000).status === 0;
const imageOk = dockerOk && run("docker", ["image", "inspect", "nginx:alpine"], 20_000).status === 0;
const opensslOk = run("openssl", ["version"], 10_000).status === 0;

describe.skipIf(!dockerOk)("docker compose config", () => {
  it("accepts docker-compose.prod.yml (placeholder env file, no real secrets read)", () => {
    const dir = mkdtempSync(join(tmpdir(), "nginx-obs-compose-"));
    try {
      const envFile = join(dir, "placeholder.env");
      writeFileSync(envFile, "");
      const override = join(dir, "override.yml");
      const y = envFile.split("\\").join("/");
      writeFileSync(
        override,
        ["services:", ...ENV_FILE_SERVICES.flatMap((s: string) => [`  ${s}:`, `    env_file: !override`, `      - ${y}`]), ""].join("\n"),
      );
      const r = run("docker", [
        "compose", "--env-file", envFile, "-f", join(REPO, "docker-compose.prod.yml"), "-f", override, "config", "--quiet",
      ]);
      expect(r.status, r.stderr).toBe(0);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }, 90_000);
});

describe.skipIf(!imageOk || !opensslOk)("nginx -t on the official image", () => {
  it("accepts the assembled conf.d (fragment + default + mail)", () => {
    const dir = mkdtempSync(join(tmpdir(), "nginx-obs-nginxt-"));
    try {
      for (const d of ["hermesnovin.com", "mail.hermesnovin.com"]) {
        const live = join(dir, "le", "live", d);
        mkdirSync(live, { recursive: true });
        const g = run("openssl", [
          "req", "-x509", "-newkey", "rsa:2048", "-nodes", "-days", "1", "-subj", `/CN=${d}`,
          "-keyout", join(live, "privkey.pem"), "-out", join(live, "fullchain.pem"),
        ]);
        expect(g.status, g.stderr).toBe(0);
        copyFileSync(join(live, "fullchain.pem"), join(live, "chain.pem"));
      }
      const n = (f: string) => join(REPO, "deploy", "nginx", f);
      const r = run("docker", [
        "run", "--rm",
        "--add-host", "hermes-web:127.0.0.1", "--add-host", "stalwart-mail:127.0.0.1",
        "-v", `${n("00-observability.conf")}:/etc/nginx/conf.d/00-observability.conf:ro`,
        "-v", `${n("default.conf")}:/etc/nginx/conf.d/default.conf:ro`,
        "-v", `${n("mail.conf")}:/etc/nginx/conf.d/mail.conf:ro`,
        "-v", `${join(dir, "le")}:/etc/letsencrypt:ro`,
        "nginx:alpine", "nginx", "-t",
      ], 90_000);
      expect(r.status, r.stderr).toBe(0);
      expect(r.stderr).toContain("test is successful");
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }, 120_000);
});
